AgAACQYAAA0AAAAAAAAAAAAAAKQBf/0EAFVuaW5zdGFsbC5wczFQSwUGAAAAADAAMACoDAAAigAFAAAA
'@

function Write-Step([string]$Text) { Write-Host ("[Ren Nev] " + $Text) -ForegroundColor Cyan }
function Fail([string]$Text) { Write-Host ("[ERROR] " + $Text) -ForegroundColor Red; throw $Text }

if ($env:OS -ne 'Windows_NT') { Fail 'Ren Nev can only be installed on Windows.' }

$InstallRoot = Join-Path $env:LOCALAPPDATA "Programs\Ren Nev's Tweaking Utility"
$StartMenuDir = Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs\Ren Nev'
$DesktopShortcut = Join-Path ([Environment]::GetFolderPath('Desktop')) "Ren Nev's Tweaking Utility.lnk"
$StartMenuShortcut = Join-Path $StartMenuDir "Ren Nev's Tweaking Utility.lnk"
$UninstallKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\RenNevTweakingUtility'
$PsExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
if (-not (Test-Path -LiteralPath $PsExe)) {
    $found = Get-Command powershell.exe -ErrorAction SilentlyContinue
    if ($found) { $PsExe = $found.Source }
}
if (-not (Test-Path -LiteralPath $PsExe)) { Fail 'Windows PowerShell 5.1 was not found.' }

$TempRoot = Join-Path $env:TEMP ('RenNevInstall-' + [Guid]::NewGuid().ToString('N'))
$ZipPath = Join-Path $TempRoot 'RenNevPayload.zip'
$Stage = Join-Path $TempRoot 'stage'
New-Item -ItemType Directory -Path $Stage -Force | Out-Null

try {
    Write-Step 'Preparing the Ren Nev app...'
    $cleanBase64 = $PayloadBase64 -replace '\s', ''
    $bytes = [Convert]::FromBase64String($cleanBase64)
    [IO.File]::WriteAllBytes($ZipPath, $bytes)

    Write-Step 'Verifying the built-in app payload...'
    $actual = (Get-FileHash -LiteralPath $ZipPath -Algorithm SHA256).Hash.ToUpperInvariant()
    if ($actual -ne $PayloadSha256.ToUpperInvariant()) {
        Fail "Payload verification failed. Expected $PayloadSha256 but got $actual. Nothing was installed."
    }

    Write-Step 'Extracting app files...'
    $expanded = $false
    try {
        Expand-Archive -LiteralPath $ZipPath -DestinationPath $Stage -Force
        $expanded = $true
    } catch { }
    if (-not $expanded) {
        try {
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            [IO.Compression.ZipFile]::ExtractToDirectory($ZipPath, $Stage)
            $expanded = $true
        } catch { }
    }
    if (-not $expanded) { Fail 'Windows could not extract the Ren Nev app payload.' }

    foreach ($required in @('RenNev.ps1','Launcher.html','Uninstall.ps1','assets\rennev.ico','assets\rennev-logo.png')) {
        $p = Join-Path $Stage $required
        if (-not (Test-Path -LiteralPath $p)) { Fail "The installer payload is incomplete: $required is missing." }
    }

    try { Get-ChildItem -LiteralPath $Stage -Recurse -File | Unblock-File -ErrorAction SilentlyContinue } catch { }

    # Close an already-running Ren Nev before updating its files.
    try {
        $oldHost = Join-Path $InstallRoot 'RenNev.ps1'
        Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" -ErrorAction SilentlyContinue | Where-Object {
            $_.ProcessId -ne $PID -and $_.CommandLine -and $_.CommandLine.IndexOf($oldHost, [StringComparison]::OrdinalIgnoreCase) -ge 0
        } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
        Start-Sleep -Milliseconds 350
    } catch { }

    Write-Step 'Installing Ren Nev for this Windows account...'
    $OldRoot = $InstallRoot + '.old'
    Remove-Item -LiteralPath $OldRoot -Recurse -Force -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $InstallRoot) { Move-Item -LiteralPath $InstallRoot -Destination $OldRoot -Force }
    try {
        New-Item -ItemType Directory -Path (Split-Path -Parent $InstallRoot) -Force | Out-Null
        Move-Item -LiteralPath $Stage -Destination $InstallRoot -Force
    } catch {
        if (Test-Path -LiteralPath $OldRoot) {
            Remove-Item -LiteralPath $InstallRoot -Recurse -Force -ErrorAction SilentlyContinue
            Move-Item -LiteralPath $OldRoot -Destination $InstallRoot -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    Remove-Item -LiteralPath $OldRoot -Recurse -Force -ErrorAction SilentlyContinue

    Write-Step 'Creating the Ren Nev shortcuts...'
    New-Item -ItemType Directory -Path $StartMenuDir -Force | Out-Null
    $Shell = New-Object -ComObject WScript.Shell
    $TargetScript = Join-Path $InstallRoot 'RenNev.ps1'
    $Icon = Join-Path $InstallRoot 'assets\rennev.ico'
    $Arguments = '-NoLogo -NoProfile -ExecutionPolicy RemoteSigned -WindowStyle Hidden -File "' + $TargetScript + '"'
    foreach ($ShortcutPath in @($DesktopShortcut, $StartMenuShortcut)) {
        $Shortcut = $Shell.CreateShortcut($ShortcutPath)
        $Shortcut.TargetPath = $PsExe
        $Shortcut.Arguments = $Arguments
        $Shortcut.WorkingDirectory = $InstallRoot
        $Shortcut.IconLocation = $Icon
        $Shortcut.Description = "Ren Nev's Tweaking Utility"
        $Shortcut.Save()
    }

    Write-Step 'Adding Ren Nev to Installed Apps...'
    New-Item -Path $UninstallKey -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name DisplayName -Value "Ren Nev's Tweaking Utility" -PropertyType String -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name DisplayVersion -Value $Version -PropertyType String -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name Publisher -Value 'Ren Nev' -PropertyType String -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name DisplayIcon -Value $Icon -PropertyType String -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name InstallLocation -Value $InstallRoot -PropertyType String -Force | Out-Null
    $UninstallPath = Join-Path $InstallRoot 'Uninstall.ps1'
    $UninstallString = '"' + $PsExe + '" -NoLogo -NoProfile -ExecutionPolicy RemoteSigned -File "' + $UninstallPath + '"'
    New-ItemProperty -Path $UninstallKey -Name UninstallString -Value $UninstallString -PropertyType String -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name NoModify -Value 1 -PropertyType DWord -Force | Out-Null
    New-ItemProperty -Path $UninstallKey -Name NoRepair -Value 1 -PropertyType DWord -Force | Out-Null

    Write-Host ''
    Write-Host "Ren Nev $Version installed successfully." -ForegroundColor Green
    Write-Host 'Desktop and Start Menu shortcuts repaired/created. No C# compiler was required.' -ForegroundColor Green
    Write-Host ''
    Write-Step 'Opening Ren Nev...'
    Start-Process -FilePath $PsExe -ArgumentList $Arguments -WorkingDirectory $InstallRoot | Out-Null
}
finally {
    Remove-Item -LiteralPath $TempRoot -Recurse -Force -ErrorAction SilentlyContinue
}
